INSERT INTO roles(code,name) VALUES ('ADMIN','Quản trị'),('SALES','Bán hàng'),('WAREHOUSE','Nhân viên kho'),('MANAGER','Quản lý cấp 1'),('DIRECTOR','Quản lý cấp 2');
INSERT INTO permissions(code,name) VALUES ('PRODUCT_READ','PRODUCT_READ'),('PRODUCT_WRITE','PRODUCT_WRITE'),('CUSTOMER_READ','CUSTOMER_READ'),('CUSTOMER_WRITE','CUSTOMER_WRITE'),('EMPLOYEE_READ','EMPLOYEE_READ'),('EMPLOYEE_WRITE','EMPLOYEE_WRITE'),('WAREHOUSE_READ','WAREHOUSE_READ'),('WAREHOUSE_WRITE','WAREHOUSE_WRITE'),('INVENTORY_READ','INVENTORY_READ'),('RECEIPT_READ','RECEIPT_READ'),('RECEIPT_WRITE','RECEIPT_WRITE'),('RECEIPT_APPROVE_1','RECEIPT_APPROVE_1'),('RECEIPT_APPROVE_2','RECEIPT_APPROVE_2'),('ORDER_READ','ORDER_READ'),('ORDER_WRITE','ORDER_WRITE'),('AUDIT_READ','AUDIT_READ'),('ACCOUNT_WRITE','ACCOUNT_WRITE'),('REPORT_READ','REPORT_READ');
INSERT INTO role_permissions SELECT r.id,p.id FROM roles r CROSS JOIN permissions p WHERE r.code='ADMIN';
INSERT INTO role_permissions SELECT r.id,p.id FROM roles r CROSS JOIN permissions p WHERE r.code='SALES' AND p.code IN ('PRODUCT_READ','CUSTOMER_READ','CUSTOMER_WRITE','ORDER_READ','ORDER_WRITE','WAREHOUSE_READ');
INSERT INTO role_permissions SELECT r.id,p.id FROM roles r CROSS JOIN permissions p WHERE r.code='WAREHOUSE' AND p.code IN ('PRODUCT_READ','WAREHOUSE_READ','INVENTORY_READ','RECEIPT_READ','RECEIPT_WRITE');
INSERT INTO role_permissions SELECT r.id,p.id FROM roles r CROSS JOIN permissions p WHERE r.code='MANAGER' AND p.code IN ('RECEIPT_READ','RECEIPT_APPROVE_1','INVENTORY_READ');
INSERT INTO role_permissions SELECT r.id,p.id FROM roles r CROSS JOIN permissions p WHERE r.code='DIRECTOR' AND p.code IN ('RECEIPT_READ','RECEIPT_APPROVE_2','REPORT_READ');
INSERT INTO warehouses(code,name) VALUES ('HCM','Kho TP. Hồ Chí Minh'),('HN','Kho Hà Nội'),('DN','Kho Đà Nẵng');
